{(event) => replace(settingsInstance.instanceId, (current) => {
                          const nextValue = event.target.value;
                          const settings = { ...(current.settings ?? {}), [key]: nextValue };
                          // A custom clock with Filter mode still on "None"
                          // looks configured but deliberately filters nothing.
                          // Selecting Custom is an explicit request to use that
                          // clock, so arm the single-window filter immediately.
                          if (key === "filterTime" && nextValue === "custom") {
                            const mode = String(settings.filterMode ?? "none");
                            if (mode !== "filter" && mode !== "splitted") settings.filterMode = "filter";
                          }
                          return { ...current, settings };
                        })}

{() => replace(settingsInstance.instanceId, (current) => {
                              const settings = { ...(current.settings ?? {}) };
                              const wasSplitting = String(settings.filterMode ?? "none") === "triple";
                              /*
                               * Every session still enabled means nothing has
                               * been PICKED yet - either the split is off, or
                               * it was armed from the Filter mode dropdown,
                               * which turns it on with all four flags true.
                               *
                               * In that state all four buttons are lit, so the
                               * first click landed as a removal: the session
                               * the trader asked for went dark and the three
                               * they did not want stayed on. Clicking a session
                               * has to mean "show me this one", so the first
                               * pick isolates it either way and only a real
                               * selection toggles.
                               */
                              /*
                               * Whether the trader has picked before, recorded
                               * rather than inferred.
                               *
                               * It used to be inferred from "are all four still
                               * on", which is true again as soon as you build
                               * the selection back up to all four - so the next
                               * click isolated instead of removing, and a lit
                               * session could not be switched off. Clicking a
                               * session did the opposite of what it looked like
                               * it would do, which is the "it doesn't do
                               * anything" that was reported.
                               */
                              const nothingPickedYet = settings.sessionSelectionArmed !== true;
                              if (!wasSplitting || nothingPickedYet) {
                                // First pick: arm the split and start from this
                                // session alone, which is what clicking one asks
                                // for. Turning on the split with everything still
                                // enabled would draw all three.
                                settings.filterMode = "triple";
                                settings.sessionSelectionArmed = true;
                                for (const sessionKey of DESK_SESSION_SETTING_KEYS) {
                                  settings[sessionKey] = sessionKey === key;
                                }
                                return { ...current, settings };
                              }
                              const enabledCount = DESK_SESSION_SETTING_KEYS
                                .filter((sessionKey) => profileSessionEnabled(settings, sessionKey)).length;
                              // Never translate "turn off the last selected
                              // session" into the unrelated whole-day mode.
                              // Keeping the final selection is deterministic
                              // and prevents the study appearing to vanish or
                              // silently changing what it measures.
                              if (profileSessionEnabled(settings, key) && enabledCount === 1) return current;
                              settings[key] = !profileSessionEnabled(settings, key);
                              const noneLeft = DESK_SESSION_SETTING_KEYS
                                .every((sessionKey) => !profileSessionEnabled(settings, sessionKey));
                              if (noneLeft) return current;
                              return { ...current, settings };
                            })}

